<section class="card"><h2>Prepare an ad draft</h2><p class="sub">Review the design, ad text, destination, and budget before publishing. Attach a photo or MP4 video to launch.</p><div class="notice">Saving a draft does not publish an ad or spend money.</div><form id="aiads-copy-form" method="post" action="<?= base_url('marketing/ai_ads/save_draft?screen=mobile'); ?>"><input type="hidden" name="<?= html_escape($csrfName); ?>" value="<?= html_escape($csrfHash); ?>"><input type="hidden" name="request_key" value="<?= bin2hex(random_bytes(20)); ?>"><label class="field">What do you want to advertise?<textarea id="aiads-prompt" name="prompt" rows="3" maxlength="3000" required placeholder="Describe the product, goal and audience"><?= html_escape($director_prefill['prompt']??''); ?></textarea></label><button class="btn" id="aiads-generate" type="button">Suggest headline and text</button> <span id="aiads-copy-status" class="muted" aria-live="polite"><?php if(!empty($director_prefill)): ?>AI video copy is ready. Review and edit before saving.<?php endif; ?></span><label class="field">Choose a product (optional)</label><label class="choice"><input type="radio" name="product_id" value="0" checked><span>No product selected</span></label><?php foreach($products as $product): ?><label class="choice"><input type="radio" name="product_id" value="<?= (int)$product['id']; ?>"><span><?= html_escape($product['item_name']); ?></span></label><?php endforeach; ?><label class="field">Location<input name="location_text" maxlength="190" placeholder="Lekki, Lagos"></label><label class="field">Daily budget (₦)<input type="number" name="daily_budget" min="0" max="100000000" step="500" placeholder="3000"></label><label class="field">Duration in days<input type="number" name="duration_days" min="1" max="365" value="30" required></label><label class="field">Attach a creative (optional)</label><label class="choice"><input type="radio" name="media_asset_id" value="0" <?= empty($generated_media_prefill)?'checked':''; ?>><span>Choose later</span></label><?php foreach(($media_assets??array()) as $asset): ?><label class="choice"><input type="radio" name="media_asset_id" value="<?= (int)$asset['id']; ?>" <?= (int)($generated_media_prefill??0)===(int)$asset['id']?'checked':''; ?>><span><?= html_escape($asset['file_name']); ?><?= (int)($generated_media_prefill??0)===(int)$asset['id']?' · newly created, review it above':''; ?></span></label><?php endforeach; ?><label class="field">Headline<input id="aiads-headline" name="headline" maxlength="255" required value="<?= html_escape($director_prefill['headline']??''); ?>"></label><label class="field">Ad text<textarea id="aiads-body" name="body" rows="4" maxlength="5000" required><?= html_escape($director_prefill['primary_text']??''); ?></textarea></label><label class="field">Where should customers go?</label><label class="choice"><input type="radio" name="destination_type" value="WEBSITE" checked><span>Website or product page · Sales</span></label><label class="choice"><input type="radio" name="destination_type" value="WHATSAPP"><span>WhatsApp · Messages</span></label><label class="field">Website conversion event (Meta Pixel required)</label><label class="choice"><input type="radio" name="conversion_event" value="PURCHASE" checked><span>Purchase</span></label><label class="choice"><input type="radio" name="conversion_event" value="ADD_TO_CART"><span>Add to cart</span></label><label class="choice"><input type="radio" name="conversion_event" value="INITIATED_CHECKOUT"><span>Begin checkout</span></label><label class="choice"><input type="radio" name="conversion_event" value="LEAD"><span>Lead</span></label><label class="choice"><input type="radio" name="conversion_event" value="VIEW_CONTENT"><span>View content</span></label><label class="field">Website or WhatsApp URL (required before publish)<input type="url" name="destination_url" placeholder="https://... or https://wa.me/234..."></label><button class="btn" type="submit">Save ad draft</button></form></section>
<?php endif; ?>
<?php if($workspace_section==='campaigns'): ?>
<section class="card"><h2>Drafts and campaigns</h2><?php if(empty($campaigns)): ?><p class="muted">No drafts yet.</p><?php else: foreach($campaigns as $campaign): ?><article class="campaign"><strong><?= html_escape($campaign['headline']?:'Untitled draft'); ?></strong> <span class="pill"><?= html_escape(ucfirst(str_replace('_',' ',$campaign['status']))); ?></span><p><?= html_escape(mb_substr($campaign['prompt'],0,140)); ?></p><p><strong>Ad text:</strong> <?= nl2br(html_escape($campaign['body']??'')); ?></p><p><strong>Destination:</strong> <?= html_escape($campaign['destination_url']??''); ?> · <?= html_escape(($campaign['destination_type']??'WEBSITE')==='WHATSAPP'?'WhatsApp messages':'Website sales · '.str_replace('_',' ',ucfirst(strtolower($campaign['conversion_event']??'PURCHASE')))); ?></p><?php if(!empty($campaign['location_text'])): ?><p><strong>Target location:</strong> <?= html_escape($campaign['location_text']); ?></p><?php endif; ?><?php if(!empty($campaign['media_asset_id'])): $creativeUrl=base_url('marketing/ai_ads/media_preview/'.(int)$campaign['media_asset_id']); ?><p><a href="<?= html_escape($creativeUrl); ?>" target="_blank" rel="noopener">Open creative preview</a></p><?php if(strpos((string)($campaign['media_mime_type']??''),'image/')===0): ?><img src="<?= html_escape($creativeUrl); ?>" alt="Ad creative preview" style="display:block;max-width:100%;max-height:360px;border-radius:8px"><?php elseif(strpos((string)($campaign['media_mime_type']??''),'video/')===0): ?><video controls preload="metadata" src="<?= html_escape($creativeUrl); ?>" style="display:block;width:100%;max-height:420px;border-radius:8px"></video><?php endif; ?><?php endif; ?><?php if($campaign['status']==='draft'): $duration=max(1,(int)ceil((strtotime($campaign['ends_at'])-strtotime($campaign['starts_at']))/86400)); $total=(int)$campaign['daily_budget_minor']*$duration; ?><form method="post" action="<?= base_url('marketing/ai_ads/publish_campaign?screen=mobile'); ?>" onsubmit="return confirm('Publish this ad on Meta? Total campaign budget: ₦<?= number_format($total/100,0); ?> for <?= $duration; ?> days. Meta bills your ad account directly.');"><input type="hidden" name="<?= html_escape($csrfName); ?>" value="<?= html_escape($csrfHash); ?>"><input type="hidden" name="campaign_id" value="<?= (int)$campaign['id']; ?>"><input type="hidden" name="confirmed_total_minor" value="<?= $total; ?>"><label class="choice"><input type="checkbox" name="approve_spend" value="1" required><span>I approve up to ₦<?= number_format($total/100,0); ?> total spend</span></label><button class="btn" type="submit" <?= empty($has_ads_access)||empty($connection['ad_account_id'])||empty($campaign['media_asset_id'])?'disabled':''; ?>>Publish ad</button></form><?php elseif($campaign['status']==='active'): ?><form method="post" action="<?= base_url('marketing/ai_ads/pause_campaign?screen=mobile'); ?>"><input type="hidden" name="<?= html_escape($csrfName); ?>" value="<?= html_escape($csrfHash); ?>"><input type="hidden" name="campaign_id" value="<?= (int)$campaign['id']; ?>"><button class="btn" type="submit">Pause ad</button></form><?php endif; ?><?php if(!empty($campaign['insights'])): $stats=$campaign['insights']; ?><p>Last 7 days: <?= number_format((int)($stats['impressions']??0)); ?> impressions · <?= number_format((int)($stats['clicks']??0)); ?> clicks · ₦<?= number_format((float)($stats['spend']??0),2); ?> spend</p><?php if(!empty($campaign['result_events'])): ?><p>Results attributed by Meta: <?= number_format((int)($campaign['result_events']['purchases']??0)); ?> purchases · <?= number_format((int)($campaign['result_events']['leads']??0)); ?> leads · <?= number_format((int)($campaign['result_events']['conversations']??0)); ?> conversations</p><?php endif; ?><?php endif; ?></article><?php endforeach; endif; ?></section>
<?php endif; ?>
</main><script>(function(){var mf=document.getElementById('aiads-media-form'),ms=document.getElementById('aiads-media-status');if(mf)mf.addEventListener('submit',function(e){e.preventDefault();var b=mf.querySelector('button[type=submit]');b.disabled=true;ms.textContent='Creating your creative… This may take a minute.';fetch(mf.action,{method:'POST',body:new FormData(mf),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'Could not create the creative.');window.location.href='<?= base_url('marketing/ai_ads/create?screen=mobile'); ?>'}).catch(function(e){ms.textContent=e.message||'Creative generation is unavailable.';b.disabled=false})});var uf=document.getElementById('aiads-upload-form'),us=document.getElementById('aiads-upload-status');if(uf)uf.addEventListener('submit',function(e){e.preventDefault();var b=uf.querySelector('button[type=submit]');b.disabled=true;us.textContent='Uploading…';fetch(uf.action,{method:'POST',body:new FormData(uf),credentials:'same-origin'}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'Could not add media.');window.location.reload()}).catch(function(e){us.textContent=e.message||'Upload failed.';b.disabled=false})})})();(function(){var b=document.getElementById('aiads-generate'),s=document.getElementById('aiads-copy-status');if(!b)return;b.addEventListener('click',function(){var p=document.getElementById('aiads-prompt').value.trim();if(!p){s.textContent='Describe your ad first.';return}b.disabled=true;s.textContent='Generating…';var d=new URLSearchParams();d.append('<?= html_escape($csrfName); ?>','<?= html_escape($csrfHash); ?>');d.append('prompt',p);d.append('product_id',(document.querySelector('input[name=product_id]:checked')||{}).value||'0');fetch('<?= base_url('marketing/ai_ads/generate_copy'); ?>',{method:'POST',headers:{'Content-Type':'application/x-www-form-urlencoded'},credentials:'same-origin',body:d.toString()}).then(function(r){return r.json()}).then(function(r){if(!r.success)throw new Error(r.message||'AI copy is unavailable.');document.getElementById('aiads-headline').value=r.copy.headline;document.getElementById('aiads-body').value=r.copy.body;s.textContent='Review and edit before saving.'+(r.usage?' ('+r.usage.used+' of '+r.usage.limit+' used this plan month).':'')}).catch(function(e){s.textContent=e.message||'AI copy unavailable.'}).finally(function(){b.disabled=false})})})();</script><?php $this->load->view('mobile/bottom_nav',array('active'=>'more')); ?><?php $this->load->view('mobile/chat'); ?></body></html>
